INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(30061, 'Luke 24:36', 'Luke', 24, 36, 'هغوی لا د دې پېښو په هکله خبرې کولې چې ناڅاپه عیسی د هغوی په منځ کې ودرېده او هغوی ته یې وویل: «په تاسو دې سلامتي وي.»', 'هغوی لا د دې پېشو په هکله خبرې کولې چې ناچاپه عیسی د هغوی په منج کې ودرېده او هغوی ته یې وویل: «په تاسو دې سلامتی وی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_24_36.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237835, 1761237835),
(30062, 'Luke 24:37', 'Luke', 24, 37, 'هغوی ټکان وخوړ او سخت ووېرېدل، ځکه ګومان یې کاوه چې د مړي ارواح ویني.', 'هغوی تکان وخور او سخت ووېرېدل، جکه ګومان یې کاوه چې د مری ارواح وینی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_24_37.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30063, 'Luke 24:38', 'Luke', 24, 38, 'خو عیسی هغوی ته وویل: «ولې دومره وارخطا یئ؟ ستاسو په زړونو کې ولې داسې شکونه پیدا کیږي؟', 'خو عیسی هغوی ته وویل: «ولې دومره وارخطا یی؟ ستاسو په زرونو کې ولې داسې شکونه پیدا کیزی؟', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_24_38.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30064, 'Luke 24:39', 'Luke', 24, 39, 'زما لاسونو او پښو ته وګورئ او وګورئ چې دا زه خپله یم. په ما لاس کېږدئ نو بیا به پوه شئ، ځکه چې ارواح غوښه او هډوکي نه لري او لکه څنګه چې تاسو یې وینئ، زه یې لرم.»', 'زما لاسونو او پشو ته وګوری او وګوری چې دا زه خپله یم. په ما لاس کېزدی نو بیا به پوه شی، جکه چې ارواح غوشه او هدوکی نه لری او لکه چنګه چې تاسو یې وینی، زه یې لرم.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_24_39.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237835, 1761237835),
(30065, 'Luke 24:40', 'Luke', 24, 40, 'کله چې هغه دا وویل، نو خپل لاسونه او پښې یې هغوی ته وښودلې.', 'کله چې هغه دا وویل، نو خپل لاسونه او پشې یې هغوی ته وشودلې.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_24_40.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30066, 'Luke 24:41', 'Luke', 24, 41, 'هغوی د ډېرې خوشحالۍ او حیرانتیا له امله نه شو کولای چې بیاهم په دې باور وکړي، نو عیسی د هغوی څخه پوښتنه وکړه: «ایا ستاسو سره دلته د خوړلو دپاره څه شته؟»', 'هغوی د دېرې خوشحالی او حیرانتیا له امله نه شو کولای چې بیاهم په دې باور وکری، نو عیسی د هغوی چخه پوشتنه وکره: «ایا ستاسو سره دلته د خورلو دپاره چه شته؟»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_24_41.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30067, 'Luke 24:42', 'Luke', 24, 42, 'هغوی ورته یوه ټوټه کباب شوی ماهي ورکړ،', 'هغوی ورته یوه توته کباب شوی ماهی ورکر،', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_24_42.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30068, 'Luke 24:43', 'Luke', 24, 43, 'نو هغه یې واخیست او د هغوی په مخکې یې وخوړ.', 'نو هغه یې واخیست او د هغوی په مخکې یې وخور.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_24_43.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30069, 'Luke 24:44', 'Luke', 24, 44, 'بیا عیسی هغوی ته وویل: «دا زما هغه خبرې دي چې کله زه ستاسو سره وم او تاسو ته به مې ویل چې هغه څه چې د موسی په تورات، د پیغمبرانو په لیکنو او د زبور په کتاب کې زما په هکله لیکل شوي دي، باید رښتیا شي.»', 'بیا عیسی هغوی ته وویل: «دا زما هغه خبرې دی چې کله زه ستاسو سره وم او تاسو ته به مې ویل چې هغه چه چې د موسی په تورات، د پیغمبرانو په لیکنو او د زبور په کتاب کې زما په هکله لیکل شوی دی، باید رشتیا شی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_24_44.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237835, 1761237835),
(30070, 'Luke 24:45', 'Luke', 24, 45, 'بیا یې د هغوی ذهنونه روښانه کړل، ترڅو د خدای په کلام پوه شي', 'بیا یې د هغوی ذهنونه روشانه کرل، ترچو د خدای په کلام پوه شی', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_24_45.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30071, 'Luke 24:46', 'Luke', 24, 46, 'او هغوی ته یې وویل: «همدارنګه لیکل شوي دي چې مسیح باید کړاوونه وویني او مړ شي او په درېمه ورځ به بیا راژوندی شي،', 'او هغوی ته یې وویل: «همدارنګه لیکل شوی دی چې مسیح باید کراوونه ووینی او مر شی او په درېمه ورج به بیا راژوندی شی،', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_24_46.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237835, 1761237835),
(30072, 'Luke 24:47', 'Luke', 24, 47, 'او د هغه په نوم به ټولو قومونو ته دا پیغام ورسول شي چې توبه وباسي او خدای به یې ګناهونه وبخښي او پیل به یې له اورشلیم څخه وي.', 'او د هغه په نوم به تولو قومونو ته دا پیغام ورسول شی چې توبه وباسی او خدای به یې ګناهونه وبخشی او پیل به یې له اورشلیم چخه وی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_24_47.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30073, 'Luke 24:48', 'Luke', 24, 48, 'تاسو د دې ټولو شیانو شاهدان یئ.', 'تاسو د دې تولو شیانو شاهدان یی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_24_48.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30074, 'Luke 24:49', 'Luke', 24, 49, 'او ګورئ، هغه څه چې زما پلار یې وعده کړې ده، درلېږم. خو باید تر هغې پورې په دې ښار کې پاتې شئ، ترڅو په تاسو باندې اسماني قوت نازل شي.» اسمان ته د عیسی ختل (مرقوس ۱۶‏:‌۱۹‌‏-‌۲۰ او د رسولانو عملونه ۱‏:‌۹‌‏-‌۱۱)', 'او ګوری، هغه چه چې زما پلار یې وعده کرې ده، درلېزم. خو باید تر هغې پورې په دې شار کې پاتې شی، ترچو په تاسو باندې اسمانی قوت نازل شی.» اسمان ته د عیسی ختل (مرقوس ۱۶‏:‌۱۹‌‏-‌۲۰ او د رسولانو عملونه ۱‏:‌۹‌‏-‌۱۱)', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_24_49.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30075, 'Luke 24:50', 'Luke', 24, 50, 'بیا عیسی هغوی د ښار څخه دباندې تر بیت‌عنیا پورې بوتلل، خپل لاسونه یې پورته کړل او هغوی ته یې برکت ورکړ', 'بیا عیسی هغوی د شار چخه دباندې تر بیت‌عنیا پورې بوتلل، خپل لاسونه یې پورته کرل او هغوی ته یې برکت ورکر', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_24_50.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30076, 'Luke 24:51', 'Luke', 24, 51, 'او په داسې حال کې چې هغوی ته یې برکت ورکاوه د هغوی څخه بېل شو او اسمان ته پورته یووړل شو.', 'او په داسې حال کې چې هغوی ته یې برکت ورکاوه د هغوی چخه بېل شو او اسمان ته پورته یوورل شو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_24_51.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30077, 'Luke 24:52', 'Luke', 24, 52, 'هغوی ورته سجده وکړه او په ډېرې خوشحالۍ سره بېرته اورشلیم ته راستانه شول.', 'هغوی ورته سجده وکره او په دېرې خوشحالی سره بېرته اورشلیم ته راستانه شول.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_24_52.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30078, 'Luke 24:53', 'Luke', 24, 53, 'هغوی خپل ټول وخت د خدای په کور کې خدای ته په ثنا ویلو تېر کړ.', 'هغوی خپل تول وخت د خدای په کور کې خدای ته په ثنا ویلو تېر کر.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_24_53.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30079, 'Luke 13:1', 'Luke', 13, 1, 'په همدې وخت کې په هغه ځای کې ځینو حاضرینو عیسی د هغو جلیلیانو څخه خبر کړ چې پیلاتوس هغوی خدای ته د قرباني وړاندې کولو په وخت کې وژلي وو.', 'په همدې وخت کې په هغه جای کې جینو حاضرینو عیسی د هغو جلیلیانو چخه خبر کر چې پیلاتوس هغوی خدای ته د قربانی وراندې کولو په وخت کې وژلی وو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_13_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30080, 'Luke 13:2', 'Luke', 13, 2, 'عیسی هغوی ته په ځواب کې وویل: «ایا ګومان کوئ چې دغه جلیلیان د جلیل له نورو ټولو اوسېدونکو څخه ډېر ګناهکاران وو چې په دې ډول ووژل شول؟', 'عیسی هغوی ته په جواب کې وویل: «ایا ګومان کوی چې دغه جلیلیان د جلیل له نورو تولو اوسېدونکو چخه دېر ګناهکاران وو چې په دې دول ووژل شول؟', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_13_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30081, 'Luke 13:3', 'Luke', 13, 3, 'نه، زه تاسو ته وایم که چېرې تاسو توبه ونه باسئ، نو تاسو ټول به د هغوی په شان تباه شئ.', 'نه، زه تاسو ته وایم که چېرې تاسو توبه ونه باسی، نو تاسو تول به د هغوی په شان تباه شی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_13_3.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237835, 1761237835),
(30082, 'Luke 13:4', 'Luke', 13, 4, 'یا هغه اتلس تنه چې په سیلوام کې ورباندې برج راوغورځېده او مړه شول، ایا ګومان کوئ چې هغوی د هغو نورو ټولو خلکو څخه چې په اورشلیم کې اوسیږي ډېر ګناهکاران وو؟', 'یا هغه اتلس تنه چې په سیلوام کې ورباندې برج راوغورجېده او مره شول، ایا ګومان کوی چې هغوی د هغو نورو تولو خلکو چخه چې په اورشلیم کې اوسیزی دېر ګناهکاران وو؟', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_13_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237835, 1761237835),
(30083, 'Luke 13:5', 'Luke', 13, 5, 'نه، زه تاسو ته وایم که چېرې توبه ونه باسئ، نو تاسو ټول به د هغوی په شان تباه شئ.» د بې‌مېوې انځر د ونې مثال', 'نه، زه تاسو ته وایم که چېرې توبه ونه باسی، نو تاسو تول به د هغوی په شان تباه شی.» د بې‌مېوې انجر د ونې مثال', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_13_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30084, 'Luke 13:6', 'Luke', 13, 6, 'بیا عیسی هغوی ته دا مثال راوړ: «یو سړي خپل د انګورو په باغ کې د انځر یوه ونه کرلې وه. کله چې راغی چې انځران راټول کړي، هېڅ یې په کې پیدا نه کړل.', 'بیا عیسی هغوی ته دا مثال راور: «یو سری خپل د انګورو په باغ کې د انجر یوه ونه کرلې وه. کله چې راغی چې انجران راتول کری، هېچ یې په کې پیدا نه کرل.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_13_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30085, 'Luke 13:7', 'Luke', 13, 7, 'نو خپل باغوان ته یې وویل: ‹ګوره، درې کاله کیږي چې راځم او په دې ونه کې مېوه لټوم، خو هېڅ مې په کې پیدا نه کړ. دا ونه ووهه. دې ونې ولې هسې ځای نیولی دی؟›', 'نو خپل باغوان ته یې وویل: ‹ګوره، درې کاله کیزی چې راجم او په دې ونه کې مېوه لتوم، خو هېچ مې په کې پیدا نه کر. دا ونه ووهه. دې ونې ولې هسې جای نیولی دی؟›', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_13_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30086, 'Luke 13:8', 'Luke', 13, 8, 'خو باغوان ورته ځواب ورکړ: ‹باداره! دا کال یې هم پرېږده، زه به د هغې شاوخوا ځمکه وکینم او سره به ورته واچوم.', 'خو باغوان ورته جواب ورکر: ‹باداره! دا کال یې هم پرېزده، زه به د هغې شاوخوا جمکه وکینم او سره به ورته واچوم.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_13_8.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237835, 1761237835),
(30087, 'Luke 13:9', 'Luke', 13, 9, 'که په راتلونکي فصل کې یې مېوه ونیوله نو ډېره ښه به وي، که نه نو بیا کولای شې چې ویې وهې.›» عیسی د سبت په ورځ یوې ښځې ته شفا ورکوي', 'که په راتلونکی فصل کې یې مېوه ونیوله نو دېره شه به وی، که نه نو بیا کولای شې چې ویې وهې.›» عیسی د سبت په ورج یوې شجې ته شفا ورکوی', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_13_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30088, 'Luke 13:10', 'Luke', 13, 10, 'د سبت په یوه ورځ عیسی په کنیسه کې تعلیم ورکاوه.', 'د سبت په یوه ورج عیسی په کنیسه کې تعلیم ورکاوه.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_13_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30089, 'Luke 13:11', 'Luke', 13, 11, 'هلته یوه ښځه وه چې اتلس کاله کېدل چې پېریانو نیولې وه او هغه یې کمزورې کړې وه. ملا یې ورته داسې کړوپه کړې وه چې بیخي سمه ودرېدلی نه شوه.', 'هلته یوه شجه وه چې اتلس کاله کېدل چې پېریانو نیولې وه او هغه یې کمزورې کرې وه. ملا یې ورته داسې کروپه کرې وه چې بیخی سمه ودرېدلی نه شوه.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_13_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
